SELECT CASE WHEN duration_sec >= 479 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, SUM(duration_sec) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart_total_duration_sec, APPROX_PERCENTILE(duration_sec, 0.95) AS duration_sec_p95, COUNT(*) AS event_count, COUNT(DISTINCT id) AS distinct_ids FROM web_events GROUP BY CASE WHEN duration_sec >= 479 THEN 'PREMIUM' ELSE 'STANDARD' END
